  (4219, 'radical', 'adjective', 'c1', '7.0 - 8.0+', '/ˈrædɪkl/', '/ˈrædɪkl/', 'cấp tiến, (chính trị) có quan điểm cực đoan', 'relating to the most basic and important parts of something; complete and detailed', 'the need for radical changes in education', 'sự cần thiết phải thay đổi căn bản trong giáo dục', ARRAY['radical changes']::text[], ARRAY['extremist', 'ultra', 'immoderate', 'revolutionary']::text[], ARRAY['moderate', 'conservative']::text[], '{"noun": "radiation"}'::jsonb, 'radical_uk.mp3', 'radical_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (4220, 'radio', 'noun', 'a1', '3.0 - 3.5', '/ˈreɪdiəʊ/', '/ˈreɪdiəʊ/', 'sóng vô tuyến, ra-đi-ô', 'the activity of broadcasting programmes for people to listen to; the programmes that are broadcast', 'The play was written specially for radio.', 'Vở kịch được viết đặc biệt cho đài phát thanh.', '{}'::text[], ARRAY['energy', 'radiocommunication', 'wireless', 'broadcasting']::text[], '{}'::text[], '{"adjective": "radical"}'::jsonb, 'radio_uk.mp3', 'radio_us.mp3', 'Arts, Media & Entertainment', 'News, Media & Broadcasting'),
