  (4225, 'railway', 'noun', 'a2', '4.0 - 4.5', '/ˈreɪlweɪ/', '/ˈreɪlweɪ/', 'đường sắt, đường có những đường ray cho tàu hoả chạy ở trên', 'a track with rails on which trains run', 'The railway is still under construction.', 'Đường sắt vẫn đang được xây dựng.', '{}'::text[], ARRAY['railroad', 'line', 'track']::text[], '{}'::text[], '{}'::jsonb, 'railway_uk.mp3', 'railway_us.mp3', 'Travel, Tourism & Transportation', 'Vehicles & Transit'),
  (4226, 'rain', 'noun', 'a1', '3.0 - 3.5', '/reɪn/', '/reɪn/', 'mưa, cơn mưa', 'water that falls from the sky in separate drops', 'There will be rain in all parts tomorrow.', 'Ngày mai sẽ có mưa ở tất cả các nơi.', ARRAY['rain in all parts']::text[], ARRAY['shower', 'downpour', 'precipitation']::text[], '{}'::text[], '{}'::jsonb, 'rain_uk.mp3', 'rain_us.mp3', 'Environment, Climate & Nature', 'Climate Change & Weather'),
  (4227, 'rain', 'verb', 'a1', '3.0 - 3.5', '/reɪn/', '/reɪn/', 'mưa, cơn mưa', 'when it rains, water falls from the sky in drops', 'Is it raining?', 'Trời có mưa không?', '{}'::text[], ARRAY['shower', 'downpour', 'precipitation']::text[], '{}'::text[], '{}'::jsonb, 'rain_uk.mp3', 'rain_us.mp3', 'Environment, Climate & Nature', 'Climate Change & Weather'),
  (4228, 'raise', 'verb', 'a2', '4.0 - 4.5', '/reɪz/', '/reɪz/', 'nâng lên, đỡ dậy, giơ lên, đưa lên, kéo lên', 'to lift or move something to a higher level', 'She raised the gun and fired.', 'Cô giơ súng lên và bắn.', '{}'::text[], ARRAY['increase', 'lift', 'boost']::text[], ARRAY['descent', 'lower', 'demote']::text[], '{}'::jsonb, 'raise_uk.mp3', 'raise_us.mp3', 'Global Issues & International Conflicts', 'Warfare & Armed Forces'),
  (4229, 'rally', 'noun', 'c1', '7.0 - 8.0+', '/ˈræli/', '/ˈræli/', 'sự tập hợp lại', 'a large public meeting, especially one held to support a particular idea or political party', 'to attend/hold a rally', 'tham dự/tổ chức một cuộc biểu tình', ARRAY['to attend/hold']::text[], ARRAY['gather', 'muster', 'regroup']::text[], ARRAY['demobilize']::text[], '{}'::jsonb, 'rally_uk.mp3', 'rally_us.mp3', 'Society, Politics & Government', 'Civil Society & Human Rights'),
